def maxJobProfit(deadlines, profits):
    n = len(deadlines)
    parent = list(range(n + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    total = 0
    order = sorted(range(n), key=lambda i: -profits[i])
    for i in order:
        slot = find(min(deadlines[i], n))
        if slot > 0:
            total += profits[i]
            parent[slot] = slot - 1
    return total
